INSERT OR IGNORE INTO "model" ("id", "comments", "created_at", "description", "descriptors", "is_deprecated", "label", "name", "properties", "provider", "type", "updated_at", "url", "version", "user_id", "release_date") VALUES ('model_e0d2a7ae-ae45-11f0-93fc-0242ac110002', NULL, '2025-10-21T06:19:19.000Z', 'GPT-4 Turbo is the next generation of GPT-4, an older high-intelligence GPT model. It was designed to be a cheaper, better version of GPT-4. Today, we recommend using a newer model like GPT-4o.', '{"top_p": {"key": "top_p", "type": "DOUBLE", "label": "Top P", "maxValue": 1, "minValue": 0, "description": "An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.", "defaultValue": 1}, "max_tokens": {"key": "max_tokens", "type": "INTEGER", "label": "Max Tokens", "maxValue": null, "minValue": 1, "description": "The maximum number of tokens to generate.", "defaultValue": null}, "temperature": {"key": "temperature", "type": "DOUBLE", "label": "Temperature", "maxValue": 2, "minValue": 0, "description": "Controls the randomness of the model output. Higher values are more random.", "defaultValue": 1}, "top_logprobs": {"key": "top_log_probs", "type": "INTEGER", "label": "Top Log Probs", "maxValue": 20, "minValue": 0, "description": "The number of most likely tokens to return at each token position, each with an associated log probability. logprobs must be set to true if this parameter is used.", "defaultValue": null}}', 0, 'GPT-4 Turbo', 'gpt-4-turbo', '{"top_p": 1.0, "max_tokens": 4096, "temperature": 1.0}', 'OPENAI', 'SYSTEM', '2025-10-21T06:19:19.000Z', 'https://api.openai.com/v1/chat/completions', NULL, 'user-e040fe2f-ae45-11f0-93fc-0242ac110002', '2023-11-06T00:00:00.000Z');
